<?php
require_once __DIR__.'/includes/db.php';$rows=db()->query("SELECT * FROM services WHERE status='active' ORDER BY sort_order,id DESC")->fetchAll();$pageTitle='Dịch vụ mạng';require __DIR__.'/includes/header.php';?><section class="hero"><small>HENDY NETWORK</small><h1>Dịch vụ mạng</h1><p>Chọn gói dịch vụ phù hợp với nhu cầu của bạn.</p></section><div class="cards"><?php foreach($rows as $r):?><article class="card"><small><?=e($r['category'])?></small><h2><?=e($r['name'])?></h2><h2 class="price"><?=number_format((float)$r['price'],0,',','.')?> đ <small>/ <?=e($r['duration'])?></small></h2><p><?=nl2br(e($r['description']))?></p><?php if($r['contact_url']):?><a class="btn" href="<?=e($r['contact_url'])?>" target="_blank" rel="noopener">Liên hệ</a><?php endif;?></article><?php endforeach;?></div><?php if(!$rows):?><p class="empty">Chưa có gói dịch vụ.</p><?php endif;?></main></body></html>